#!/usr/bin/env python3
"""Deterministic, dependency-free build of the primary 16-day trip dashboard.
Older parallel sites and source data are intentionally never rewritten.
"""
import json
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/full-trip.json').read_text())
S={s['id']:s for s in json.loads((ROOT/'data/current-sources.json').read_text())}
rows=D['rows']; days=D['days']
e=lambda v:escape(str(v),quote=True)
NAV=[('index.html','◈','Overview'),('itinerary.html','▤','Day by day'),('transit.html','↗','Getting around'),('stays.html','⌂','Your hotels'),('attractions.html','◎','Places & experiences'),('food-shopping.html','♧','Eat & shop'),('flagged-for-review.html','⚑','Flagged for Review'),('sources.html','↗','Sources & method')]
def refs(ids,context=False):
 return ''.join(f'<a class="source" href="{e(S[k]["url"])}" target="_blank" rel="noopener noreferrer">{e(S[k]["label"])} ↗</a>' for k in ids)+('<small class="context">Context only · does not verify this item</small>' if context else '')
def tag(r):return f'<span class="badge {r["status"]}">{"Partly sourced" if r["status"]=="partial" else "Unverified"}</span>'
def table(rs,label):
 out=f'<div class="table-wrap" tabindex="0" role="region" aria-label="{e(label)}"><table><caption class="sr-only">{e(label)}</caption><thead><tr><th scope="col">Plan & place</th><th scope="col">Hours & closed days</th><th scope="col">Location & price</th><th scope="col">Evidence & review</th></tr></thead><tbody>'
 for r in rs:
  out+=f'<tr data-search="{e(json.dumps(r,ensure_ascii=False).lower())}" data-status="{r["status"]}" data-category="{e(r["category"])}" id="{r["id"]}"><td data-label="Plan & place"><span class="meta">Day {r["day"]} · {e(r["category"])} · {r["id"]}</span><strong>{e(r["item"])}</strong><p class="proposal">{e(r["plan"])}</p><small>Proposed order: {e(r["time"])}</small></td><td data-label="Hours & closed days"><dl><dt>Published hours</dt><dd>{e(r["hours"])}</dd><dt>Closed / exceptions</dt><dd>{e(r["closed"])}</dd></dl></td><td data-label="Location & price"><dl><dt>Official location</dt><dd>{e(r["address"])}</dd><dt>Published price</dt><dd>{e(r["price"])}</dd></dl></td><td data-label="Evidence & review">{tag(r)}<p>{e(r["facts"])}</p><details><summary>Review note</summary><p>{e(r["flag"])}</p></details>{refs(r["sourceIds"],r["status"]=="unverified")}</td></tr>'
 return out+'</tbody></table></div>'
def controls():return '<div class="filterbar"><label class="searchbox"><span aria-hidden="true">⌕</span><span class="sr-only">Search this page</span><input type="search" id="search" placeholder="Search places, dishes or routes…"></label><label class="sr-only" for="status-filter">Evidence status</label><select id="status-filter"><option value="all">All evidence statuses</option><option value="partial">Partly sourced</option><option value="unverified">Unverified</option></select><span id="result-count" role="status"></span></div><p class="empty" id="empty-results" hidden>No matching entries. Try a different search or evidence filter.</p>'
def shell(file,title,subtitle,body):
 current='aria-current="page"'
 nav=''.join(f'<a href="{url}" {current if url==file else ""}><span aria-hidden="true">{icon}</span>{label}</a>' for url,icon,label in NAV)
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A source-linked 16-day Korea itinerary for two adults: Seoul, Busan and Hongdae. Verified fields, transport references and visible review notes."><meta name="theme-color" content="#173f39"><title>{e(title)} · Korea, together</title><link rel="stylesheet" href="styles.css"><script defer src="app.js"></script></head>
<body><a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="index.html"><span class="brand-icon">K</span><span>Korea, together<small>YOUR PERSONAL TRAVEL GUIDE</small></span></a><p class="nav-label">THE JOURNEY</p><nav aria-label="Main navigation">{nav}</nav><div class="side-bottom"><span class="tiny-dot"></span> Made for two adults<p>Seoul → Busan → Seoul</p><small>Travel year not confirmed</small></div></aside><div class="site"><header class="topbar"><span>TRAVEL NOTEBOOK <span class="separator">/</span> SOUTH KOREA</span><div class="top-actions"><span class="audit-dot"></span> Audit · 26 Oct 2026<button type="button" class="print-button">Print / save PDF</button></div></header><main id="main"><div class="page-heading"><div><p class="eyebrow">A LITTLE PLANNING. A LOT TO DISCOVER.</p><h1>{e(title)}</h1><p>{e(subtitle)}</p></div><span class="country-stamp">KR<br><b>SOUTH KOREA</b></span></div>{body}<footer><span>Korea, together <b>·</b> 2 adults <b>·</b> 16 planned days</span><span>Audit snapshot: 26 Oct 2026 · not live opening status<br><a href="sources.html">Method & source limitations</a> · <a href="archives.html">Earlier research archives</a></span></footer></main></div></body></html>'''
def save(file,title,subtitle,body): (ROOT/file).write_text(shell(file,title,subtitle,body))
def section(kicker,title,aside=''):return f'<div class="section-heading"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2></div>{aside}</div>'
blanknote='<p class="legend"><span class="badge partial">Partly sourced</span> Only displayed facts are supported. <span class="badge unverified">Unverified</span> No venue facts confirmed. <b>Blank fields are intentionally unconfirmed.</b> Plans and visit times are your proposals, not bookings. Prices are per person unless stated; age concessions may apply.</p>'
alert='<a class="notice" href="flagged-for-review.html"><span class="notice-symbol">!</span><span><b>Two things before you go</b><br>The travel year is unresolved, and the Tuesday palace visit conflicts with its regular closure.</span><span aria-hidden="true">↗</span></a>'
# Skyline is authored decorative vector, not a purported photograph.
art='''<svg class="city-art" viewBox="0 0 560 210" aria-hidden="true"><circle cx="410" cy="55" r="35" fill="#e9c992" opacity=".8"/><path d="M0 190Q80 150 150 175T300 160T560 160V210H0Z" fill="#668d79"/><path d="M15 185L100 108L140 145L200 95L260 180" fill="#7a9f89"/><g fill="#b1c0a3" stroke="#173f39" stroke-width="2"><path d="M120 190V143H161V190M162 190V128H193V190M370 190V114H402V190M413 190V93H437V190M446 190V128H482V190"/><path d="M224 188V94H236V188M218 94V83H242V94M230 83V31M214 72H246M220 60H240" fill="#c8c7a5"/><path d="M281 188V155H348V188M271 155Q310 134 358 155Z" fill="#e6cf9e"/></g><g stroke="#e7dfbe" stroke-width="3"><path d="M0 193H560M377 135H396M377 147H396M377 159H396M419 115H432M419 127H432M419 139H432M453 147H475M453 159H475M131 157H151M131 169H151"/></g><path d="M300 188Q410 145 550 177M300 188L550 188M335 171V188M380 162V188M430 161V188M480 167V188M530 174V188" fill="none" stroke="#f0d5a3" stroke-width="3"/><path d="M37 65H90M61 53H115M469 50H520" stroke="#c4d2b8" stroke-width="2"/></svg>'''
hero=f'<section class="journey-banner"><div><span class="banner-tag">YOUR KOREA FIELD GUIDE</span><h2>City mornings.<br>Coastal evenings.</h2><p>One journey, three home bases.<br>All your plans in one place.</p><a class="button light" href="itinerary.html#day-1">Explore the itinerary <span>↗</span></a></div>{art}<div class="banner-route"><span><i></i> SEOUL <small>Myeongdong</small></span><b>→</b><span><i></i> BUSAN <small>Haeundae</small></span><b>→</b><span><i></i> SEOUL <small>Hongdae</small></span></div></section>'
count=sum(r['status']=='partial' for r in rows)
stats=f'<section class="stats" aria-label="Trip at a glance"><div><span class="stat-icon">▤</span><span><b>16 <small>days</small></b><small>A plan you can browse</small></span></div><div><span class="stat-icon">⌂</span><span><b>3 <small>home bases</small></b><small>Hotels from your draft</small></span></div><div><span class="stat-icon">◎</span><span><b>{len(rows)} <small>entries</small></b><small>Including open days & alternatives</small></span></div><div><span class="stat-icon">↗</span><span><b>{len(S)} <small>official references</small></b><small>{count} entries with some sourced facts</small></span></div></section>'
cardgroups=''
for label,ids in [('01 — SEOUL · MYEONGDONG',range(1,9)),('02 — TO THE COAST · BUSAN',range(9,16)),('03 — BACK TO SEOUL · HONGDAE',[16])]:
 cardgroups+=f'<h3 class="week-label">{label}</h3><div class="day-grid">'
 for i in ids:
  d=days[i-1];open_day=i in [8,13,15]
  closure='<span class="closure">Tuesday closure conflict</span>'
  cardgroups+=f'<a class="day-tile {"transfer" if d["city"]=="Transfer" else ""}" href="itinerary.html#day-{i}"><div class="tile-top"><span class="day-num">{i:02}</span><span class="tile-day">{e(d["date"].split(" · ")[0])}</span><span class="tile-arrow">↗</span></div><span class="tile-city">{e(d["city"])}</span><h3>{e(d["title"])}</h3><p>{e(d["outline"])}</p><div class="tile-footer">{closure if i==3 else "Open / flexible" if open_day else "View day plan"}<span>→</span></div></a>'
 cardgroups+='</div>'
save('index.html','Your Korea journey','A thoughtful plan for two. From Seoul’s neighborhood streets to Busan’s coast, and back again.',hero+stats+alert+section('SIXTEEN DAYS, AT YOUR PACE','Where will the day take you?','<a class="text-link" href="itinerary.html">Day-by-day view ↗</a>')+'<p class="muted">Select a day for the full plan, transport references, published hours and review notes. No dates or bookings have been invented.</p>'+cardgroups)
# Real static sections retain full content without JavaScript; hash enhances to a single selected day.
chips='<nav class="day-picker" aria-label="Choose a day">'+''.join(f'<a href="#day-{i}" data-day="{i}"><small>DAY</small>{i:02}</a>' for i in range(1,17))+'</nav>'
body=alert+chips+'<div class="day-toolbar"><a href="itinerary.html#day-1" id="previous-day">← Previous day</a><button class="show-all" type="button" id="show-all">Show all days</button><a href="itinerary.html#day-2" id="next-day">Next day →</a></div>'+controls()+blanknote
for d in days:
 i=d['day'];dr=[r for r in rows if r['day']==i]
 body+=f'<section class="day-section" id="day-{i}" data-day-section="{i}"><div class="day-title"><span class="big-day">{i:02}</span><div><p class="eyebrow">{e(d["city"])} · {e(d["date"])}</p><h2>{e(d["title"])}</h2></div><span class="entry-count">{len(dr)} entries</span></div><div class="day-base"><span>⌂ <b>Home base</b> {e(d["hotel"])}</span><span>↗ <b>Day flow</b> {e(d["outline"])}</span></div><p class="day-note"><b>Planning note</b> · {e(d["note"])}</p>{table(dr,f"Day {i} itinerary")}</section>'
save('itinerary.html','One day at a time','Choose a day. Your proposed plan and official-source facts sit side by side.',body)
for file,title,sub,cat in [
 ('transit.html','Getting around','Station-to-station options, hotel transfer gaps and booking links. Exact fares and times stay blank when unconfirmed.',['Transit','Travel']),
 ('stays.html','Your three home bases','The hotels in your draft, with published policies kept separate from your reservations.',['Stay']),
 ('food-shopping.html','Good food. Great finds.','Every café, market, restaurant, bar and store in your draft — including the names still needing confirmation.',['Food','Shopping','Nightlife']),
 ('attractions.html','Places & experiences','Palaces, neighborhoods, coastal walks and memorable views. Published hours are not a trip-date guarantee.',['Activities']),
 ('dining.html','At the table','Restaurant, market and nightlife entries from the full 16-day draft.',['Food','Nightlife']),
 ('shopping.html','Shops & neighborhoods','Shopping entries, with branch-level gaps left visible.',['Shopping'])]:
 extra=''
 if file=='transit.html':
  extra='<div class="callout"><b>The important distinction</b><p>AREX Express runs non-stop between ICN and Seoul Station. Day 16 needs the <strong>all-stop</strong> service for Hongik University. KTX needs a separate, date-specific ticket for each direction.</p>'+refs(['airport','korail'])+'</div>'
 if file=='stays.html':
  extra='<div class="hotel-strip"><article><span>01 · SEOUL</span><h2>Stanford Myeongdong</h2><p>Days 1–8 · depart Day 9</p>'+refs(['stanford','stanford-address'])+'</article><article><span>02 · BUSAN</span><h2>L7 HAEUNDAE</h2><p>Days 9–15 · depart Day 16</p>'+refs(['l7'])+'</article><article><span>03 · SEOUL</span><h2>Mercure Hongdae</h2><p>Arrive Day 16 · departure not supplied</p>'+refs(['mercure'])+'</article></div><p class="muted">Stays above follow the proposed day sequence, not confirmed bookings or calendar dates.</p>'
 save(file,title,sub,extra+controls()+blanknote+table([r for r in rows if r['category'] in cat],title))
# All issues linked to official references; flags never silently waived.
body='<div class="callout warning"><b>A transparent plan, not a false promise</b><p>Unresolved items do not prevent publication. They do limit what you should rely on. No exact date, ticket availability, reservation or live opening status is implied.</p></div>'
body+=section('START HERE','High-priority findings')
findings=[('Unresolved year & dates','“Nov 2, 2006” conflicts with the Monday label. Dates for Days 10–16 were not supplied. Do not infer a year from the weekday pattern.',['seoul']),('Tuesday palace closure','Day 3 cannot be relied on as written. Gyeongbokgung is normally closed Tuesdays; a public-holiday exception needs a confirmed date.',['palace']),('Sky Capsule return is not automatic','Operator lists one-way trips and one-way capsule packages. A skywalk visit is not transport back to your hotel. Confirm a return plan separately.',['capsule','capsule-book']),('Conflicting official addresses & hours','Kyoja has conflicting English/Korean addresses; Cheongsapo has conflicting official closing times. The affected exact fields remain blank.',['kyoja','daritdol','skywalks']),('Duplicate stops & backtracking','Day 9 was repeated in the draft and is included once. X the SKY appears Days 10 and 12. Day 11 repeats Nampo-area visits before and after Songdo. These are planning findings, not new venue facts.',['xsky','nampo']),('Archives are not current evidence','Older parallel views include assumptions about 2026 and different KTX fares. They remain for provenance only; this primary view does not inherit those unsupported claims.',['korail'])]
body+='<div class="table-wrap"><table><thead><tr><th scope="col">Finding</th><th scope="col">Why it matters</th><th scope="col">Official reference</th></tr></thead><tbody>'+''.join(f'<tr><td><strong>{e(t)}</strong></td><td>{e(x)}</td><td>{refs(s)}</td></tr>' for t,x,s in findings)+'</tbody></table></div>'
body+=section('FULL REGISTER','Every entry’s remaining caveats')+controls()+blanknote+table(rows,'Flagged for Review register')
save('flagged-for-review.html','Flagged for Review','The uncertainties, conflicts and missing details — clearly labeled, never quietly filled in.',body)
save('flagged.html','Flagged for Review','The primary review register now covers the complete 16-day trip.','<div class="callout"><h2>All review notes, in one place</h2><p>Use the current full-trip register rather than the older Days 1–9 table.</p><a class="button" href="flagged-for-review.html">Open Flagged for Review ↗</a></div>')
method='<div class="callout"><b>How to read this guide</b><p>Proposed plans come from your itinerary. Sourced facts come only from official operator, government or tourism pages checked in this session. “Partly sourced” does not verify the whole row. Unknown hours, closure days, addresses and prices stay empty. Context-only links are explicitly labeled and do not confirm named businesses.</p><p>Sources checked 26 October 2026, not a travel-year assumption. Search extracts are labeled below; they are not represented as full-page reads. Exact operational conditions, reservations and performance cancellations require live confirmation. No currency conversion, invented transit duration or date-specific availability is supplied.</p></div>'
method+=section('AUDIT TRAIL','Official-source register')+'<p class="muted">Each source records the checked material and its limitations. Archived facts are not carried forward automatically.</p>'+controls()
method+='<div class="table-wrap"><table><thead><tr><th scope="col">Reference</th><th scope="col">Material checked</th><th scope="col">Scope & limitations</th></tr></thead><tbody>'
for s in S.values():method+=f'<tr data-search="{e(json.dumps(s,ensure_ascii=False).lower())}" data-status="partial"><td><strong>{e(s["label"])}</strong><small>{e(s["method"])} · {s["checked"]}</small>{refs([s["id"]])}</td><td>{e(s["evidence"])}</td><td>{e(s["limitation"])}</td></tr>'
method+='</tbody></table></div><p><a href="data/full-trip.json" download>Download full itinerary JSON ↗</a> · <a href="data/current-sources.json" download>Download source register ↗</a> · <a href="data/itinerary-raw.md">Original Days 1–9 transcription ↗</a> · <a href="data/full-trip-addendum.md">Submitted Week 2 ↗</a> · <a href="data/audit-attempts.md">Failed / limited source attempts ↗</a></p>'
save('sources.html','Sources & method','An inspectable evidence trail. Every itinerary row links to an official reference, with context-only links clearly distinguished.',method)
save('analysis.html','Planning findings','What the full-trip audit means for a practical travel day.','<div class="callout"><h2>Plan with the gaps in view</h2><p>Current analysis is integrated into each day’s planning note and the review register.</p><a class="button" href="flagged-for-review.html">Read findings & caveats ↗</a></div>'+''.join(f'<article class="analysis-card"><p class="eyebrow">DAY {d["day"]}</p><h2>{e(d["title"])}</h2><p>{e(d["note"])}</p><a href="itinerary.html#day-{d["day"]}">Open day plan →</a></article>' for d in days))
archives='<div class="callout warning"><b>Historical research, not the current trip guide</b><p>These parallel sessions were preserved without rewriting their content. Some assume 2026, cover only Days 1–9 or include prices from secondary sources. Their claims are not independently endorsed by this audit. Use the primary 16-day dashboard for the current evidence policy.</p></div><div class="archive-grid">'+''.join(f'<a class="analysis-card" href="{url}"><h2>{e(title)}</h2><span>Open archived view ↗</span></a>' for url,title in [('previous-dashboard/index.html','Parallel full-trip dashboard snapshot'),('complete/index.html','Parallel complete day pages'),('guide/index.html','Parallel tap-a-day guide'),('docs/index.html','Initial research site'),('docs/trip-guide/index.html','Earlier trip guide'),('trip/index.html','Earlier daily pages'),('portal/index.html','Earlier transit portal'),('source-audit/index.html','Earlier source audit'),('verified/index.html','Earlier verified view')])+'</div>'
save('archives.html','Research archives','Previous parallel-session contributions, preserved for provenance and manual review.',archives)
print(f'Built 13 primary pages from {len(rows)} entries / {len(days)} days / {len(S)} sources')
